codeExamples.code:
-- Query a previous version of the table
SELECT * FROM delta.`s3://lakehouse/silver/customers` VERSION AS OF 12;

-- Or by timestamp
SELECT * FROM delta.`s3://lakehouse/silver/customers`
TIMESTAMP AS OF '2026-06-10T00:00:00';

-- Inspect history of commits
DESCRIBE HISTORY delta.`s3://lakehouse/silver/customers`;

-- Compact small files and cluster data for faster scans
OPTIMIZE delta.`s3://lakehouse/silver/customers` ZORDER BY (region);

-- Remove files no longer referenced (retention threshold)
VACUUM delta.`s3://lakehouse/silver/customers` RETAIN 168 HOURS;
